public sealed class TimeBlock {public string id="",taskId="",date="",time="09:00";public int minutes=60;}
public sealed class WeekOptions {public int capacity=480;}
internal sealed class PlanningEvent {internal string title;internal DateTime start,end;internal bool allDay;}
internal static class WeeklyPlanning {
 internal static void Validate(Data d){if(d.timeBlocks==null)d.timeBlocks=new List<TimeBlock>();if(d.settings.Week==null)d.settings.Week=new WeekOptions();if(d.settings.Week.capacity<60||d.settings.Week.capacity>1440||d.timeBlocks.Count>10000)throw new InvalidDataException("Planning invalide.");var ids=new HashSet<string>();foreach(var b in d.timeBlocks){if(b==null||String.IsNullOrWhiteSpace(b.id)||b.id.Length>100||!ids.Add(b.id)||String.IsNullOrWhiteSpace(b.taskId)||b.taskId.Length>100||!Finance.DateOk(b.date)||!Schedule.ValidTime(b.time)||b.minutes<15||b.minutes>720||Schedule.At(b.date,b.time).Date!=Schedule.At(b.date,b.time).AddMinutes(b.minutes-1).Date)throw new InvalidDataException("Créneau invalide (15 min à 12 h, dans la même journée).");}}
 internal static TimeBlock Dropped(Data d,string value,DateTime day,int minute){minute=Math.Max(0,Math.Min(1425,minute));var old=value.StartsWith("block/",StringComparison.Ordinal)?d.timeBlocks.FirstOrDefault(b=>b.id==value.Substring(6)):null;string task=old==null?(value.StartsWith("task/",StringComparison.Ordinal)?value.Substring(5):""):old.taskId;if(!d.tasks.Any(t=>t.id==task))return null;return new TimeBlock{id=old==null?Guid.NewGuid().ToString():old.id,taskId=task,date=day.ToString("yyyy-MM-dd"),time=day.Date.AddMinutes(minute).ToString("HH:mm"),minutes=Math.Min(old==null?60:old.minutes,1440-minute)};}
 internal static bool Overlap(DateTime a,int length,DateTime b,int other){return a<b.AddMinutes(other)&&b<a.AddMinutes(length);}
 internal static int MinutesOnDay(DateTime start,DateTime end,DateTime day){var from=start>day.Date?start:day.Date;var until=end<day.Date.AddDays(1)?end:day.Date.AddDays(1);return (int)Math.Max(0,(until-from).TotalMinutes);}
 internal static int Load(Data d,DateTime day){string key=day.ToString("yyyy-MM-dd");return d.timeBlocks.Where(b=>b.date==key&&d.tasks.Any(t=>t.id==b.taskId&&t.status!="done")).Sum(b=>b.minutes)+d.events.Sum(e=>MinutesOnDay(Schedule.At(e.date,e.time),Schedule.At(e.date,e.time).AddMinutes(e.duration),day));}
 internal static List<string> Conflicts(Data d,TimeBlock block){var at=Schedule.At(block.date,block.time);return d.timeBlocks.Where(b=>b.id!=block.id&&d.tasks.Any(t=>t.id==b.taskId&&t.status!="done")&&Overlap(at,block.minutes,Schedule.At(b.date,b.time),b.minutes)).Select(b=>d.tasks.First(t=>t.id==b.taskId).title).Concat(d.events.Where(e=>Overlap(at,block.minutes,Schedule.At(e.date,e.time),e.duration)).Select(e=>e.title)).ToList();}
 internal static void Save(Store store,TimeBlock block){if(!store.Value.tasks.Any(t=>t.id==block.taskId&&t.status!="done"))throw new InvalidDataException("Choisissez une tâche active.");PersonalWorkflows.Change(store,()=>{store.Value.timeBlocks.RemoveAll(b=>b.id==block.id);store.Value.timeBlocks.Add(block);});}
}
internal sealed partial class ModernWorkspace {
 System.Collections.Generic.List<PlanningEvent> PlanningGoogleEvents(){var result=new System.Collections.Generic.List<PlanningEvent>();foreach(var e in calendarEvents)try{var start=GoogleCalendarClient.LocalStart(e);var end=GoogleCalendarClient.LocalStart(new GoogleCalendarEvent{start=e.end});if(end>start)result.Add(new PlanningEvent{title=e.summary,start=start,end=end,allDay=!String.IsNullOrEmpty(e.start.date)});}catch{}return result;}
 bool planningFullDay;DateTime planningDay=DateTime.Today;string planningQuery="";const string PlanningFormat="MonEspace.Planning";readonly string planningSession=Guid.NewGuid().ToString("N");
