  var tools=new WrapPanel{Margin=new Thickness(0,0,0,15)};tools.Children.Add(Btn("‹",()=>{planningDay=planningDay.AddDays(-7);Refresh();},false,true));tools.Children.Add(Btn("Cette semaine",()=>{planningDay=DateTime.Today;Refresh();},true));tools.Children.Add(Btn("›",()=>{planningDay=planningDay.AddDays(7);Refresh();},false,true));tools.Children.Add(Btn("+ Planifier une tâche",()=>EditTimeBlock(null,planningDay,"09:00")));tools.Children.Add(Btn("Capacité quotidienne",EditWeekCapacity,false,true));tools.Children.Add(Btn(planningFullDay?"Vue 06h–minuit":"Afficher les 24 heures",()=>{planningFullDay=!planningFullDay;Refresh();},false,true));var google=Btn("Actualiser Google",delegate{if(CalendarSession()==null){Go("Agenda");return;}agendaDate=planningDay;SyncGoogleCalendar();},false,true);google.IsEnabled=!googleBusy;tools.Children.Add(google);body.Children.Add(tools);body.Children.Add(T("Les rendez-vous Google affichés sont ceux déjà chargés depuis Agenda. Actualisez-les pour cette période ; l’absence d’événement chargé ne garantit pas un créneau libre.",11,Muted,new Thickness(0,0,0,12)));
  var monday=planningDay.Date.AddDays(-((int)planningDay.DayOfWeek+6)%7);body.Children.Add(T("Semaine du "+monday.ToString("dd MMMM",CultureInfo.GetCultureInfo("fr-FR")),18,Ink,new Thickness(0,0,0,12)));
  var search=new TextBox{Text=planningQuery,ToolTip="Rechercher une tâche à planifier",MaxLength=180};var pending=new WrapPanel{Margin=new Thickness(0,8,0,14)};Action render=delegate{pending.Children.Clear();planningQuery=search.Text;foreach(var t in store.Value.tasks.Where(t=>t.status!="done"&&(t.title+" "+t.project).IndexOf(planningQuery,StringComparison.CurrentCultureIgnoreCase)>=0).OrderBy(t=>t.due).Take(30)){var task=t;var b=Btn(t.title,()=>EditTimeBlock(new TimeBlock{id=Guid.NewGuid().ToString(),taskId=task.id},planningDay,"09:00"),false,true);b.ToolTip="Cliquer pour choisir un créneau ou glisser sur une journée";Point start=new Point();b.PreviewMouseLeftButtonDown+=delegate(object s,MouseButtonEventArgs e){start=e.GetPosition(b);};b.PreviewMouseMove+=delegate(object s,MouseEventArgs e){if(e.LeftButton==MouseButtonState.Pressed&&(e.GetPosition(b)-start).Length>SystemParameters.MinimumHorizontalDragDistance){DragDrop.DoDragDrop(b,new DataObject(PlanningFormat,planningSession+"/task/"+task.id),DragDropEffects.Move);}};pending.Children.Add(b);}};search.TextChanged+=delegate{render();};Field(body,"À planifier · rechercher une tâche",search);body.Children.Add(pending);render();
  body.Children.Add(T("Glissez une tâche sur un horaire. Cliquez sur un créneau pour modifier sa durée. Les chevauchements restent visibles ; les échéances des tâches restent indépendantes.",11,Muted,new Thickness(0,0,0,16)));
  var headers=new Grid();headers.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(40)});for(int h=0;h<7;h++)headers.ColumnDefinitions.Add(new ColumnDefinition());var grid=new Grid();grid.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(40)});for(int i=0;i<7;i++)grid.ColumnDefinitions.Add(new ColumnDefinition());grid.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});grid.RowDefinitions.Add(new RowDefinition());
  var hours=new Canvas{Height=(24-startHour)*48};for(int h=startHour;h<24;h++){var label=T(h.ToString("00"),10,Muted);Canvas.SetTop(label,(h-startHour)*48);hours.Children.Add(label);}Grid.SetRow(hours,1);grid.Children.Add(hours);
  for(int i=0;i<7;i++){var day=monday.AddDays(i);string key=day.ToString("yyyy-MM-dd");int googleMinutes=PlanningGoogleEvents().Where(e=>!e.allDay).Sum(e=>WeeklyPlanning.MinutesOnDay(e.start,e.end,day));int load=WeeklyPlanning.Load(store.Value,day)+googleMinutes;var header=new StackPanel{Margin=new Thickness(4,0,4,12)};header.Children.Add(T(day.ToString("ddd dd",CultureInfo.GetCultureInfo("fr-FR")),12,day==DateTime.Today?Accent:Ink));header.Children.Add(T((load/60.0).ToString("0.#")+" h / "+(store.Value.settings.Week.capacity/60.0).ToString("0.#")+" h",10,load>store.Value.settings.Week.capacity?Accent:Muted));if(load>store.Value.settings.Week.capacity)header.Children.Add(T("Journée chargée",10,Accent));Grid.SetColumn(header,i+1);headers.Children.Add(header);
   var canvas=new Canvas{Height=(24-startHour)*48,Background=SurfaceBrush,AllowDrop=true,ClipToBounds=true,Margin=new Thickness(2,0,2,0)};for(int h=startHour;h<24;h++){var line=new Border{Height=1,Width=1500,Background=FaintLine};Canvas.SetTop(line,(h-startHour)*48);canvas.Children.Add(line);}
   Action<string,string,int,Action,bool> tile=delegate(string title,string time,int length,Action action,bool external){var b=Btn("",action,false,true);var panel=new StackPanel();panel.Children.Add(T(title,10,external?Muted:Ink));panel.Children.Add(T(time+" · "+length+" min",9,Muted));b.Content=panel;b.Background=external?CardBg:SelectionBrush;b.Padding=new Thickness(5);b.Margin=new Thickness(1);b.Height=Math.Max(22,length*.8);b.ToolTip=title+" · "+time+" · "+length+" min";b.Width=Math.Max(72,90);Canvas.SetLeft(b,1);Canvas.SetTop(b,(TimeSpan.Parse(time).TotalMinutes-startHour*60)*.8);canvas.Children.Add(b);};
   foreach(var b in store.Value.timeBlocks.Where(b=>b.date==key&&store.Value.tasks.Any(t=>t.id==b.taskId)).OrderBy(b=>b.time)){var block=b;var task=store.Value.tasks.First(t=>t.id==b.taskId);tile((task.status=="done"?"✓ ":WeeklyPlanning.Conflicts(store.Value,b).Count>0?"⚠ ":"")+task.title,b.time,b.minutes,()=>EditTimeBlock(block,day,block.time),false);var drag=canvas.Children.OfType<Button>().Last();Point origin=new Point();drag.PreviewMouseLeftButtonDown+=delegate(object sender,MouseButtonEventArgs e){origin=e.GetPosition(drag);};drag.PreviewMouseMove+=delegate(object sender,MouseEventArgs e){if(e.LeftButton==MouseButtonState.Pressed&&(e.GetPosition(drag)-origin).Length>SystemParameters.MinimumHorizontalDragDistance)DragDrop.DoDragDrop(drag,new DataObject(PlanningFormat,planningSession+"/block/"+block.id),DragDropEffects.Move);};}
   foreach(var appointment in store.Value.events.Where(e=>WeeklyPlanning.MinutesOnDay(Schedule.At(e.date,e.time),Schedule.At(e.date,e.time).AddMinutes(e.duration),day)>0)){var ev=appointment;var start=Schedule.At(ev.date,ev.time);tile("RDV · "+ev.title,(start<day?day:start).ToString("HH:mm"),WeeklyPlanning.MinutesOnDay(start,start.AddMinutes(ev.duration),day),()=>EditAppointment(ev,day),true);}
   foreach(var appointment in PlanningGoogleEvents().Where(e=>!e.allDay&&WeeklyPlanning.MinutesOnDay(e.start,e.end,day)>0)){var ev=appointment;tile("Google · "+ev.title,(ev.start<day?day:ev.start).ToString("HH:mm"),WeeklyPlanning.MinutesOnDay(ev.start,ev.end,day),()=>Go("Agenda"),true);}
   foreach(var ev in PlanningGoogleEvents().Where(e=>e.allDay&&e.start.Date<=day&&e.end.Date>day))header.Children.Add(T("Google · "+ev.title,9,Muted));
