 void LayoutPlanningTiles(Canvas canvas){var cards=canvas.Children.OfType<Button>().OrderBy(b=>Canvas.GetTop(b)).ToList();var ends=new System.Collections.Generic.List<double>();var lanes=new System.Collections.Generic.Dictionary<Button,int>();foreach(var b in cards){double at=Canvas.GetTop(b);int lane=ends.FindIndex(v=>v<=at);if(lane<0){lane=ends.Count;ends.Add(0);}ends[lane]=at+b.Height;lanes[b]=lane;}int count=Math.Max(1,ends.Count);double width=Math.Max(36,(canvas.ActualWidth>0?canvas.ActualWidth:96)/count-2);foreach(var b in cards){b.Width=width;Canvas.SetLeft(b,lanes[b]*(width+2));}}
 string PlanningDrag(IDataObject data){if(!data.GetDataPresent(PlanningFormat))return null;var value=data.GetData(PlanningFormat) as string;return value!=null&&value.StartsWith(planningSession+"/",StringComparison.Ordinal)?value.Substring(planningSession.Length+1):null;}
 void EditWeekCapacity(){StackPanel body,actions;var w=Dialog("Capacité quotidienne",out body,out actions,450);var hours=new TextBox{Text=(store.Value.settings.Week.capacity/60.0).ToString("0.#")};Field(body,"Heures disponibles par jour (1 à 24)",hours);var error=T("",12,Accent);body.Children.Add(error);actions.Children.Add(Btn("Enregistrer",delegate{double value;if(!Double.TryParse(hours.Text.Replace(',', '.'),NumberStyles.Float,CultureInfo.InvariantCulture,out value)||value<1||value>24){error.Text="Indiquez entre 1 et 24 heures.";return;}try{PersonalWorkflows.Change(store,()=>store.Value.settings.Week.capacity=(int)(value*60));FinishFinanceDialog(w);}catch(Exception ex){error.Text=ex.Message;}},true));ShowWindow(w);Refresh();}
 void EditTimeBlock(TimeBlock existing,DateTime day,string at){StackPanel body,actions;var w=Dialog("Planifier une tâche",out body,out actions,650);var tasks=store.Value.tasks.Where(t=>t.status!="done"||(existing!=null&&t.id==existing.taskId)).OrderBy(t=>t.title).ToList();var task=new ComboBox{ItemsSource=tasks,DisplayMemberPath="title",SelectedIndex=Math.Max(0,tasks.FindIndex(t=>existing!=null&&t.id==existing.taskId))};Field(body,"Tâche",task);bool stored=existing!=null&&store.Value.timeBlocks.Any(b=>b.id==existing.id);var date=new TextBox{Text=(stored?Schedule.Day(existing.date):day).ToString("dd/MM/yyyy")};Field(body,"Date",date);var time=new TextBox{Text=at};Field(body,"Heure",time);var duration=new TextBox{Text=(existing==null?60:existing.minutes).ToString()};Field(body,"Durée en minutes",duration);var conflicts=T("",12,Accent);body.Children.Add(conflicts);Action preview=delegate{string parsed;int minutes;if(ReadDate(date,true,out parsed)&&Schedule.ValidTime(time.Text)&&Int32.TryParse(duration.Text,out minutes)&&minutes>0){var probe=new TimeBlock{id=existing==null?"":existing.id,date=parsed,time=time.Text,minutes=minutes};var list=WeeklyPlanning.Conflicts(store.Value,probe);int google=PlanningGoogleEvents().Count(e=>!e.allDay&&WeeklyPlanning.Overlap(Schedule.At(parsed,time.Text),minutes,e.start,(int)Math.Max(1,(e.end-e.start).TotalMinutes)));conflicts.Text=list.Count+google>0?"Chevauchement : "+String.Join(", ",list)+(google>0?" · "+google+" rendez-vous Google":""):"Créneau disponible parmi les éléments chargés.";}};date.TextChanged+=delegate{preview();};time.TextChanged+=delegate{preview();};duration.TextChanged+=delegate{preview();};preview();body.Children.Add(T("Planifier une tâche ne change ni son échéance ni son statut.",11,Muted));if(stored)actions.Children.Add(Btn("Retirer du planning",delegate{try{PersonalWorkflows.Change(store,()=>store.Value.timeBlocks.RemoveAll(b=>b.id==existing.id));FinishFinanceDialog(w);}catch(Exception ex){conflicts.Text=ex.Message;}},false,true));actions.Children.Add(Btn("Annuler",delegate{w.Close();},false,true));actions.Children.Add(Btn("Enregistrer",delegate{string parsed;int minutes;var selectedTask=task.SelectedItem as WorkTask;if(selectedTask==null||!ReadDate(date,true,out parsed)||!Schedule.ValidTime(time.Text)||!Int32.TryParse(duration.Text,out minutes)){conflicts.Text="Vérifiez la tâche, la date, l’heure et la durée.";return;}try{WeeklyPlanning.Save(store,new TimeBlock{id=existing==null?Guid.NewGuid().ToString():existing.id,taskId=selectedTask.id,date=parsed,time=time.Text,minutes=minutes});FinishFinanceDialog(w);}catch(Exception ex){conflicts.Text=ex.Message;}},true));ShowWindow(w);Refresh();}
